def config_value(text: str, key: str) -> str:
    """Return the value for key in name=value per-line config text, or empty string if absent."""
    result: str = ""
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        k, sep, v = line.partition("=")
        if sep and k.strip() == key:
            result = v.strip()
    return result


def test_config_value_present() -> None:
    text = "host=localhost\nport=8080"
    assert config_value(text, "host") == "localhost"
    assert config_value(text, "port") == "8080"


def test_config_value_absent() -> None:
    text = "host=localhost\nport=8080"
    assert config_value(text, "missing") == ""


def test_config_value_empty_text() -> None:
    assert config_value("", "key") == ""


def test_config_value_whitespace_handling() -> None:
    text = "  host  =  127.0.0.1  \nport=80"
    assert config_value(text, "host") == "127.0.0.1"


def test_config_value_comments_and_blank_lines() -> None:
    text = "# A comment\n\nhost=localhost\n  # Another comment"
    assert config_value(text, "host") == "localhost"
    assert config_value(text, "comment") == ""


def test_config_value_multiple_equals() -> None:
    text = "query=page=1&limit=10"
    assert config_value(text, "query") == "page=1&limit=10"


def test_config_value_empty_value() -> None:
    text = "flag="
    assert config_value(text, "flag") == ""


def test_config_value_later_override() -> None:
    text = "timeout=10\ntimeout=20"
    assert config_value(text, "timeout") == "20"

